const normalize=s=>String(s||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().trim();
function merge(existing=[]){const result=existing.map(f=>({...f})),ids=new Set(existing.map(f=>f.id)),names=new Set(existing.map(f=>normalize(f.name)));for(const f of foods){if(!ids.has(f.id)&&!names.has(normalize(f.name))){result.push({...f});ids.add(f.id);names.add(normalize(f.name));}}return result;}
return {version:1,foods,merge};
